import{_ as i,l as n,o as e,c as l,v as t,p as s,x as r,d,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"默认配置加固","description":"","frontmatter":{"title":"默认配置加固","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/default-config-hardening.md","filePath":"cs/default-config-hardening.md","lastUpdated":1789023840000}'),p={name:"cs/default-config-hardening.md"};function E(_,a,f,u,m,A){const o=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="默认配置加固" tabindex="-1">默认配置加固 <a class="header-anchor" href="#默认配置加固" aria-label="Permalink to &quot;默认配置加固&quot;">​</a></h1><div class="epigraph"><p>出厂默认口令、开放管理口、示例虚拟主机，是扫描后最便宜的入口。加固基线把「开箱可用」收成「开箱最小」。</p><footer>—— 据 CIS Benchmarks 的基线思想；NIST SP 800-123；对照 Anderson 对默认</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/network-segmentation">分段</a>假定段内主机不是默认口令。缺口是<strong>主机与中间件默认</strong>。本课讲基线，不写利用默认口令的步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>设备管理界面默认账户、数据库空口令、目录列表。缺口是黄金镜像、配置即代码、关闭示例。</p><h3 id="云安全组" tabindex="-1">云安全组 <a class="header-anchor" href="#云安全组" aria-label="Permalink to &quot;云安全组&quot;">​</a></h3><p>默认 0.0.0.0/0 是分段失败。</p><p><span class="marginnote">CIS。禁止默认口令利用教程。SIEM 下一课把加固后的日志收走。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照 CIS/STIG 清单作过程，不是一次勾选。下一课 SIEM 与日志。</p>',12)),(e(),s(c,null,{default:r(()=>[h(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEF%5B%22%E5%87%BA%E5%8E%82%E9%BB%98%E8%AE%A4%22%5D%20--%3E%20ATT%5B%22%E6%89%AB%E6%8F%8F%E5%8D%B3%E4%B8%AD%22%5D%0A%20%20BASE%5B%22%E5%9F%BA%E7%BA%BF%E9%95%9C%E5%83%8F%22%5D%20--%3E%20MIN%5B%22%E6%9C%80%E5%B0%8F%E6%9C%8D%E5%8A%A1%E4%B8%8E%E5%8F%A3%E4%BB%A4%E7%AD%96%E7%95%A5%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>攻击面来自忘记改的合同。日志下一课让改没改可被看见。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写对默认管理口的利用。出厂状态要当成敌意的初始条件。SIEM 下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分段挡跨区；默认口令在段内仍开大门。</li><li>基线镜像与配置即代码。</li><li>云安全组默认全开等于无分段。</li><li>下一课 SIEM。</li><li>出处：CIS Benchmarks；NIST SP 800-123；Anderson。</li></ul>',8))])}const T=i(p,[["render",E]]);export{B as __pageData,T as default};
